1	/**
2	 * Washer-world materials: procedural perforated magenta metal (round holes for drums, circumferential
3	 * slots for tunnels), thick reflective gold, chrome, glass — all PBR (MeshStandardMaterial) so they pick
4	 * up the candy PMREM environment, with shader patches for the perforations and glow.
5	 */
6	import * as THREE from 'three';
7	
8	export interface PerforatedOptions {
9	  /** base metal colour */
10	  color?: THREE.ColorRepresentation;
11	  /** colour of the hole interiors */
12	  holeColor?: THREE.ColorRepresentation;
13	  /** 0 = round holes (drum), 1 = slots elongated along u (tunnel rings) */
14	  slot?: number;
15	  /** pattern repeats: holes around u (per 0..1) and per uv-unit along v */
16	  repeatU?: number;
17	  repeatV?: number;
18	  /** hole size relative to its cell (0..1) */
19	  holeSize?: number;
20	  emissive?: THREE.ColorRepresentation;
21	  emissiveIntensity?: number;
22	  metalness?: number;
23	  roughness?: number;
24	  side?: THREE.Side;
25	  /** bright stripe highlights running along v (tunnel light streaks) */
26	  streaks?: number;
27	  /** number of procedural lengthwise streaks around u (default 9) */
28	  streakCount?: number;
29	  /**
30	   * explicit slot half-size in CELL units [along u, along v] (overrides holeSize/slot); the cell is
31	   * 1/repeatU of the circumference by 1/repeatV along the tube, so world proportions follow from both
32	   */
33	  slotHalf?: [number, number];
34	  /** stagger every other slot row by half a cell (default true) */
35	  stagger?: boolean;
36	  /** pattern offset along v in cells (aligns slot rows between the ring bands) */
37	  offsetV?: number;
38	  /**
39	   * Washer-tube upgrade (05–07): pressed-metal corrugation + bevelled slot lips perturb the normal so
40	   * the glossy metal catches light around every slot (refs 05–07). Height amplitudes in world units.
41	   */
42	  relief?: { corrugation: number; bevel: number; bevelWidth?: number };
43	  /** emissive glow colour hugging every hole edge (refs: hot-pink glowing slot outlines) */
44	  rimColor?: THREE.ColorRepresentation;
45	  rimStrength?: number;
46	  /** warm "light at the end of the tunnel": emissive that grows with view distance */
47	  farGlow?: FarGlow;
48	  /** dedicated reflection environment (e.g. washerTubeEnv()) instead of scene.environment */
49	  envMap?: THREE.Texture | null;
50	  envMapIntensity?: number;
51	  /**
52	   * forced-perspective section (05 far tunnel): the geometry carries a per-vertex `fgExtra` attribute =
53	   * virtual minus real depth, so the distance glow / mid tint behave as if the tunnel ran on for hundreds
54	   * of units (see buildForcedTunnel in tube.ts)
55	   */
56	  virtualDepth?: boolean;
57	  /**
58	   * paint a far stream on the tunnel floor (forced-perspective section only): band centred on the
59	   * bottom (uv.x = 0.5), half width in uv.x, visible beyond `from` virtual units
60	   */
61	  river?: { halfWidth: number; from: number; core: THREE.ColorRepresentation; band: THREE.ColorRepresentation; foam: THREE.ColorRepresentation };
62	}
63	
64	export interface FarGlow {
65	  color: THREE.ColorRepresentation; near: number; far: number; strength: number;
66	  /** optional mid-distance tint of the metal colour (refs: walls turn violet deeper in the tunnel) */
67	  mid?: { color: THREE.ColorRepresentation; near: number; far: number; amount: number };
68	}
69	
70	/** GLSL for the distance glow, shared by the tube wall, rings and lids. With FG_VIRTUAL the distance is the
71	 *  forced-perspective (virtual) depth: real view distance + the per-vertex/per-instance `fgExtra`. */
72	const FAR_GLOW_PARS = `uniform vec3 uFarGlowColor; uniform vec3 uFarGlowRange; uniform vec3 uMidTint; uniform vec3 uMidRange;
73	#ifdef FG_VIRTUAL
74	varying float vFgExtra;
75	float fgDist(){ return length(vViewPosition) + vFgExtra; }
76	#else
77	float fgDist(){ return length(vViewPosition); }
78	#endif
79	float farGlowK(){ float k = smoothstep(uFarGlowRange.x, uFarGlowRange.y, fgDist()); return uFarGlowRange.z * k * k; }
80	float midTintK(){ return uMidRange.z * smoothstep(uMidRange.x, uMidRange.y, fgDist()); }`;
81	/** vertex side of FG_VIRTUAL: `fgExtra` is a plain attribute on tube geometry, an instanced one on rings/lids */
82	const FG_VIRTUAL_VERT_PARS = `#ifdef FG_VIRTUAL
83	attribute float fgExtra; varying float vFgExtra;
84	#endif`;
85	const FG_VIRTUAL_VERT = `#ifdef FG_VIRTUAL
86	vFgExtra = fgExtra;
87	#endif`;
88	/** `solid` = 0 inside perforation holes (they stay dark), 1 on metal */
89	const FAR_GLOW_APPLY = (solid = '1.0') => `{ float sol = ${solid}; float mt = midTintK() * sol; diffuseColor.rgb = mix(diffuseColor.rgb, uMidTint, mt); totalEmissiveRadiance *= 1.0 - mt * 0.5;
90	  float fg = farGlowK(); diffuseColor.rgb = mix(diffuseColor.rgb, uFarGlowColor, min(1.0, fg * 0.5) * sol); totalEmissiveRadiance += uFarGlowColor * fg * mix(0.35, 1.0, sol); }`;
91	
92	function farGlowUniforms(g: FarGlow) {
93	  return {
94	    uFarGlowColor: { value: new THREE.Color(g.color) },
95	    uFarGlowRange: { value: new THREE.Vector3(g.near, g.far, g.strength) },
96	    uMidTint: { value: new THREE.Color(g.mid?.color ?? '#ffffff') },
97	    uMidRange: { value: new THREE.Vector3(g.mid?.near ?? 0, g.mid?.far ?? 1, g.mid?.amount ?? 0) },
98	  };
99	}
100	
101	/**
102	 * Adds the warm distance glow to any MeshStandardMaterial (rings, lids). The far end of the tube melts
103	 * into a bright warm vanishing point like refs 05/07 without adding scene lights (mobile-friendly).
104	 */
105	export function withFarGlow<T extends THREE.MeshStandardMaterial>(mat: T, g: FarGlow, key: string, virtualDepth = false): T {
106	  const uniforms = farGlowUniforms(g);
107	  const prev = mat.onBeforeCompile;
108	  if (virtualDepth) mat.defines = { ...(mat.defines ?? {}), FG_VIRTUAL: '' };
109	  mat.onBeforeCompile = (shader, r) => {
110	    prev.call(mat, shader, r);
111	    Object.assign(shader.uniforms, uniforms);
112	    if (virtualDepth) {
113	      shader.vertexShader = shader.vertexShader
114	        .replace('#include <common>', '#include <common>\n' + FG_VIRTUAL_VERT_PARS)
115	        .replace('#include <project_vertex>', '#include <project_vertex>\n' + FG_VIRTUAL_VERT);
116	    }
117	    shader.fragmentShader = shader.fragmentShader
118	      .replace('#include <common>', '#include <common>\n' + FAR_GLOW_PARS)
119	      .replace(
120	        '#include <emissivemap_fragment>',
121	        `#include <emissivemap_fragment>
122	${FAR_GLOW_APPLY()}`,
123	      );
124	  };
125	  const prevKey = mat.customProgramCacheKey.bind(mat);
126	  mat.customProgramCacheKey = () => prevKey() + '|fg2-' + key + (virtualDepth ? '-v' : '');
127	  mat.userData.farGlow = uniforms;
128	  return mat;
129	}
130	
131	/**
132	 * Analytic strip lights for the washer tubes (refs 05–07). Narrow light strips run the full length of
133	 * the tunnel at evenly spaced angles around its axis. Their radiance depends only on the azimuth of the
134	 * reflected view ray around the LOCAL tube axis, so (unlike a cube map, whose meridians pinch together
135	 * and blur at the pole every grazing wall reflection looks into) they stay crisp at any distance and
136	 * follow the tube through the 06 arch and the 07 plunge. The term is added to the IBL radiance, so the
137	 * normal PBR BRDF weights it: glossy magenta panels get lengthwise white-pink streaks, every gold band
138	 * gets evenly spaced "marquee" spots, and both line up radially like in the reference.
139	 * Axis source: 'attribute' = per-vertex `tubeAxis`/`tubeUp` (buildTubeGeometry({ axisAttr: true })),
140	 * 'instance' = local Z (axis) / local Y (up) of each instance matrix (rings, lids).
141	 */
142	export interface TubeStrips {
143	  count: number;
144	  /** angular half-width of one strip (radians, before roughness widening) */
145	  width: number;
146	  intensity: number;
147	  color: THREE.ColorRepresentation;
148	  /** brightness of every other strip (default 0.7) */
149	  alt?: number;
150	}
151	
152	export function withTubeStrips<T extends THREE.MeshStandardMaterial>(mat: T, s: TubeStrips, source: 'attribute' | 'instance', key: string): T {
153	  const uniforms = {
154	    uStripColor: { value: new THREE.Color(s.color).multiplyScalar(s.intensity) },
155	    uStripP: { value: new THREE.Vector4(s.count, s.width, 0, s.alt ?? 0.7) },
156	  };
157	  const prev = mat.onBeforeCompile;
158	  mat.onBeforeCompile = (shader, r) => {
159	    prev.call(mat, shader, r);
160	    Object.assign(shader.uniforms, uniforms);
161	    const axis = source === 'instance'
162	      ? `vTubeAxis = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 0.0, 1.0, 0.0)).xyz);
163	vTubeUp = normalize((viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 1.0, 0.0, 0.0)).xyz);`
164	      : `vTubeAxis = normalize((viewMatrix * modelMatrix * vec4(tubeAxis, 0.0)).xyz);
165	vTubeUp = normalize((viewMatrix * modelMatrix * vec4(tubeUp, 0.0)).xyz);`;
166	    shader.vertexShader = shader.vertexShader
167	      .replace('#include <common>', `#include <common>
168	varying vec3 vTubeAxis; varying vec3 vTubeUp;
169	${source === 'attribute' ? 'attribute vec3 tubeAxis; attribute vec3 tubeUp;' : ''}`)
170	      .replace('#include <project_vertex>', `#include <project_vertex>
171	${axis}`);
172	    shader.fragmentShader = shader.fragmentShader
173	      .replace('#include <common>', `#include <common>
174	varying vec3 vTubeAxis; varying vec3 vTubeUp; uniform vec3 uStripColor; uniform vec4 uStripP;
175	vec3 tubeStripRadiance(vec3 V, vec3 N, float rough){
176	  vec3 R = reflect(-V, N);
177	  vec3 A = normalize(vTubeAxis);
178	  vec3 E1 = normalize(vTubeUp - A * dot(vTubeUp, A));
179	  vec3 E2 = cross(A, E1);
180	  vec3 P = R - A * dot(R, A);
181	  float pl = length(P);
182	  float t = atan(dot(P, E2), dot(P, E1)) * uStripP.x / 6.2831853; // strip index space
183	  float fw = min(fwidth(t), fwidth(fract(t + 0.5)));
184	  float w0 = uStripP.y * uStripP.x / 6.2831853;            // half-width in pitch units
185	  float w = w0 + rough * rough * 1.5 + fw * 0.6;
186	  float dA = fract(t + 0.5) - 0.5;
187	  float k = exp(-dA * dA / (w * w)) * mix(1.0, w0 / w, 0.75);
188	  k *= mod(floor(t + 0.5), 2.0) > 0.5 ? uStripP.w : 1.0;
189	  return uStripColor * k * smoothstep(0.02, 0.12, pl);
190	}`)
191	      .replace('#include <lights_fragment_maps>', `#include <lights_fragment_maps>
192	#if defined( RE_IndirectSpecular )
193	radiance += tubeStripRadiance(geometryViewDir, geometryNormal, material.roughness);
194	#endif`);
195	  };
196	  const prevKey = mat.customProgramCacheKey.bind(mat);
197	  mat.customProgramCacheKey = () => prevKey() + '|strips-' + source + '-' + key;
198	  mat.userData.tubeStrips = uniforms;
199	  return mat;
200	}
201	
202	/** linear radiance for a stylised palette entry: the values are solved so that, after Neutral tone mapping
203	 *  (exposure 0.86), sRGB output and the grade pass (sat 1.36 / con 1.15), they land on the display colour
204	 *  sampled from the approved reference (comment = target display sRGB) */
205	const lin3 = (r: number, g: number, b: number) => new THREE.Vector3(r, g, b);
206	
207	/**
208	 * Ref 05 ring look (wave 7): a stylised polished band instead of the env-map PBR result (which clipped to one
209	 * flat orange). The band profile (roundBandGeometry: main half-round band, groove, camera-side lip) is read
210	 * from the object-space axial coordinate, so every ring — near, real far, forced-perspective far — gets the
211	 * same cross-section: dark rose contour at both edges → rose-copper → orange line → peach-gold body → pale
212	 * white-yellow highlight line on the crown, a darker orange-copper groove, and a rose lip with a light crown.
213	 * Warm-white "marquee" spots sit at `count` fixed azimuths (top spot at 12 o'clock) so the spots of all rings
214	 * line up radially toward the VP like the reference. Deeper rings fade to rose-copper (ref rings #2/#3); the
215	 * FarGlow (if the material has one) then melts them into the warm throat. Measured reference cross-section
216	 * (ring #1, y 188→230 at x≈499): dark (161,32,91) · rose lip (219,96,104) · groove (202,67,51) · peach body
217	 * (241,154,124) with white spots · rose (206,96,104) · dark (122,30,84); side view (y≈450): orange (251,135,29)
218	 * then pale yellow crown (252,205,130).
219	 */
220	export interface BandShade {
221	  /** band profile (same numbers as the BandOpts given to bandGeometry) */
222	  width: number; lipWidth: number; groove: number;
223	  /** spots per turn, spot half-width (fraction of the pitch), spot strength */
224	  spots?: [number, number, number];
225	  /** view distance range over which the crown highlight fades to rose-copper (deeper rings) */
226	  fade?: [number, number];
227	}
228	export function withBandShading<T extends THREE.MeshStandardMaterial>(mat: T, b: BandShade, key: string): T {
229	  const w = (b.width + b.groove + b.lipWidth) / 2;
230	  const uniforms = {
231	    uBandG: { value: new THREE.Vector4(w - b.width / 2, b.width / 2, -w + b.lipWidth / 2, b.lipWidth / 2) },
232	    // ref ring #1: spot pitch ≈85 px at r 273 (≈20/turn), white core ≈12 px inside a yellow halo
233	    uBandS: { value: new THREE.Vector4(...(b.spots ?? [20, 0.055, 1.6]), 0) },
234	    uBandF: { value: new THREE.Vector2(...(b.fade ?? [44, 110])) },
235	    uBcDark: { value: lin3(0.2934, 0.0886, 0.1533) }, // (150,35,85)
236	    uBcRose: { value: lin3(0.5899, 0.2114, 0.2222) }, // (215,95,100)
237	    uBcOrange: { value: lin3(0.7352, 0.2871, 0.1269) }, // (240,120,40)
238	    uBcCrown: { value: lin3(0.6246, 0.22, 0.199) }, // (222,98,88) rose-gold body between the spots (ref (215–230,90–100,80–95))
239	    uBcPeak: { value: lin3(0.9077, 0.602, 0.3465) }, // (252,190,120) highlight line
240	    uBcHalo: { value: lin3(0.9439, 0.6846, 0.2725) }, // (255,205,90) yellow halo around each spot
241	    uBcGroove: { value: lin3(0.4938, 0.1484, 0.1192) }, // (200,70,50)
242	    uBcSpot: { value: lin3(1.6, 1.5, 1.3) }, // warm white, blooms a little
243	  };
244	  const prev = mat.onBeforeCompile;
245	  mat.onBeforeCompile = (shader, r) => {
246	    prev.call(mat, shader, r);
247	    Object.assign(shader.uniforms, uniforms);
248	    shader.vertexShader = shader.vertexShader
249	      .replace('#include <common>', '#include <common>\nvarying vec3 vBandP; varying vec3 vBandAx;')
250	      .replace('#include <begin_vertex>', `#include <begin_vertex>
251	vBandP = position;
252	#ifdef USE_INSTANCING
253	vBandAx = (viewMatrix * modelMatrix * instanceMatrix * vec4(0.0, 0.0, 1.0, 0.0)).xyz;
254	#else
255	vBandAx = (viewMatrix * modelMatrix * vec4(0.0, 0.0, 1.0, 0.0)).xyz;
256	#endif`);
257	    const fg = shader.fragmentShader.includes('float farGlowK()');
258	    shader.fragmentShader = shader.fragmentShader
259	      .replace('void main() {', `varying vec3 vBandP; varying vec3 vBandAx;
260	uniform vec4 uBandG; uniform vec4 uBandS; uniform vec2 uBandF;
261	uniform vec3 uBcDark; uniform vec3 uBcRose; uniform vec3 uBcOrange; uniform vec3 uBcCrown; uniform vec3 uBcPeak; uniform vec3 uBcGroove; uniform vec3 uBcSpot; uniform vec3 uBcHalo;
262	// The rider sees every band at a grazing angle, i.e. mostly its camera-facing flank: the colour therefore
263	// follows the view-space normal — facing (ndv) for body → orange line → rose → dark silhouette contour, the
264	// normal's axial component (nzv: -1 camera-facing base … 0 crown) for the highlight line — and the axial
265	// coordinate only for the thin dark contour lines where band and lip meet the wall and for the groove.
266	vec3 bandShade(float deep, vec3 N, vec3 V){
267	  float z = vBandP.z;
268	  float m = (z - uBandG.x) / uBandG.y;          // main band: -1 camera side … +1 far side
269	  float l = (z - uBandG.z) / uBandG.w;          // lip
270	  float fm = fwidth(m) + 1e-3, fl = fwidth(l) + 1e-3;
271	  // sign-robust: the forced-perspective rings are placed with a mirrored basis (inverted winding), so the
272	  // rendered side can face away; shade the camera-facing orientation of whatever side is drawn
273	  float nv = dot(N, V);
274	  float ndv = abs(nv);
275	  vec3 ax = normalize(vBandAx);
276	  ax *= sign(dot(ax, -V) + 1e-4);                // tube axis pointing away from the camera
277	  float nzv = dot(N * sign(nv + 1e-4), ax);      // -1 = flank facing the camera … 0 = crown
278	  vec3 body = mix(uBcCrown, mix(uBcRose * 1.12, uBcCrown, 0.3), deep);   // deeper rings: rose-copper body
279	  vec3 c = mix(uBcDark, uBcRose, smoothstep(0.03, 0.14, ndv));
280	  c = mix(c, uBcOrange, smoothstep(0.16, 0.26, ndv));
281	  c = mix(c, body, smoothstep(0.3, 0.46, ndv));
282	  float hl = exp(-pow((nzv + 0.8) / 0.07, 2.0)) * smoothstep(0.3, 0.5, ndv);
283	  c = mix(c, uBcPeak, hl * (0.95 - 0.6 * deep));
284	  c = mix(c, uBcDark, smoothstep(0.9, 1.0, abs(m)) * 0.85);           // contour where the band meets the wall
285	  vec3 cl = mix(uBcDark, mix(uBcRose, uBcCrown, 0.55 - 0.35 * deep), smoothstep(0.05, 0.3, ndv));
286	  cl = mix(cl, uBcDark, smoothstep(0.86, 1.0, abs(l)) * 0.85);
287	  float inMain = smoothstep(-1.0 - fm, -1.0 + fm, m);
288	  float inLip = 1.0 - smoothstep(1.0 - fl, 1.0 + fl, l);
289	  vec3 col = mix(uBcGroove, cl, inLip);
290	  col = mix(col, c, inMain);
291	  // marquee spots at fixed azimuths (12 o'clock = a spot): radial lines of spots into the VP
292	  float phi = atan(vBandP.y, vBandP.x);
293	  float t = (phi - 1.5707963) * uBandS.x / 6.2831853;
294	  float ft = min(fwidth(t), fwidth(fract(t + 0.5)));
295	  float d = fract(t + 0.5) - 0.5;
296	  float sw = uBandS.y + ft * 0.7, hw = uBandS.y * 3.0 + ft * 0.7;
297	  float sp = exp(-d * d / (sw * sw)) * mix(1.0, uBandS.y / sw, 0.6);
298	  float halo = exp(-d * d / (hw * hw));
299	  float across = inMain * smoothstep(0.25, 0.5, ndv) * (1.0 - smoothstep(0.93, 0.99, abs(m))) + inLip * (1.0 - inMain) * 0.4 * smoothstep(0.2, 0.4, ndv);
300	  col = mix(col, uBcHalo, halo * across * 0.8);
301	  col += uBcSpot * sp * across * uBandS.z * (1.0 - 0.4 * deep);
302	  return col;
303	}
304	void main() {`)
305	      .replace('#include <opaque_fragment>', `{
306	  float bDist = length(vViewPosition);
307	${fg ? '  bDist = fgDist();' : ''}
308	  vec3 bc = bandShade(smoothstep(uBandF.x, uBandF.y, bDist), normalize(normal), normalize(vViewPosition));
309	${fg ? `  float bfg = farGlowK(); float bmt = midTintK();
310	  bc = mix(bc, uFarGlowColor * 0.9, min(1.0, bfg * 0.55)) + uFarGlowColor * bfg * 0.25;` : ''}
311	  outgoingLight = bc;
312	}
313	#include <opaque_fragment>`);
314	  };
315	  const prevKey = mat.customProgramCacheKey.bind(mat);
316	  mat.customProgramCacheKey = () => prevKey() + '|band-' + key;
317	  mat.userData.bandShade = uniforms;
318	  return mat;
319	}
320	
321	/**
322	 * Ref 05 wall lids (wave 7): stylised rose-copper half-disc pucks seen from below (reference L1/R1: rim
323	 * (229,91,93)…(246,130,114) with white vertical highlight streaks and a bright top edge line, a lighter
324	 * rose-peach underside with a thin orange contour). Regions come from the object-space normal of the lid
325	 * lathe (wallLidGeometry, half revolution toward +X, Y = top normal), the streaks from the lathe azimuth.
326	 */
327	export function withLidShading<T extends THREE.MeshStandardMaterial>(mat: T, key: string): T {
328	  const uniforms = {
329	    uLcRim: { value: lin3(0.612, 0.2117, 0.2013) }, // (220,95,90)
