567	  if (cached) return cached;
568	  const isGold = variant !== 'wall';
569	  const N = 128;
570	  const dir = new THREE.Vector3();
571	  const col = new THREE.Color();
572	  const faces: THREE.DataTexture[] = [];
573	  // cube face orientation (same convention as WebGL cube maps)
574	  const faceDir = (f: number, a: number, b: number) => {
575	    switch (f) {
576	      case 0: return dir.set(1, -b, -a);
577	      case 1: return dir.set(-1, -b, a);
578	      case 2: return dir.set(a, 1, b);
579	      case 3: return dir.set(a, -1, -b);
580	      case 4: return dir.set(a, -b, 1);
581	      default: return dir.set(-a, -b, -1);
582	    }
583	  };
584	  // Smooth base only: the strip lights are analytic (withTubeStrips), because grazing wall reflections all
585	  // look almost straight down the tunnel, where a cube map's meridian strips pinch together and blur.
586	  // gold (wave 4): warm yellow-white above (polished yellow-gold mids/highlights, ref #F4B70F…#FCE082),
587	  // copper only toward the floor (shadowed side); was amber 0.62/0.24/0.07 → saturated orange rings
588	  // 'gold05' (wave 5, 05 rings/lids only): brighter pale-yellow sky (ref highlights #FCE082) over a copper
589	  // floor, so the bands read yellow-gold with copper only on the shadowed side
590	  const cBaseTop = variant === 'gold05' ? new THREE.Color(0.95, 0.8, 0.4) : isGold ? new THREE.Color(0.78, 0.56, 0.24) : new THREE.Color(0.5, 0.04, 0.36);
591	  const cBaseLow = variant === 'gold05' ? new THREE.Color(0.36, 0.15, 0.05) : isGold ? new THREE.Color(0.26, 0.09, 0.04) : new THREE.Color(0.17, 0.035, 0.44);
592	  const copper05 = new THREE.Color(0.42, 0.15, 0.035);
593	  const radiance = (d: THREE.Vector3, out: THREE.Color) => {
594	    const up = d.y;
595	    if (variant === 'gold05') {
596	      // saturated gold all round (no dark gaps between the marquee spots), pale yellow toward the light at
597	      // the tunnel end (-Z), from above and back toward the rider (the camera-facing slope of every band),
598	      // copper only straight down: the shadowed lower side of each band
