608	      out.r += 2.0 * hot; out.g += 1.85 * hot; out.b += 1.1 * hot;
609	      return out;
610	    }
611	    // base: magenta above, violet toward the floor
612	    out.copy(cBaseTop).lerp(cBaseLow, THREE.MathUtils.smoothstep(-up, -0.3, 0.9));
613	    // gold only: a warm yellow-white core at the very end of the tunnel (-Z) so far bands glow like the VP
614	    const ahead = Math.max(0, -d.z);
615	    if (isGold) {
616	      const hot = Math.pow(ahead, 60), wide = Math.pow(ahead, 6);
617	      out.r += 2.0 * hot + 0.16 * wide; out.g += 1.85 * hot + 0.12 * wide; out.b += 1.1 * hot + 0.04 * wide;
618	    } else {
619	      const wide = Math.pow(ahead, 6);
620	      out.r += 0.04 * wide; out.g += 0.015 * wide; out.b += 0.2 * wide; // violet haze down the tunnel
621	    }
622	    return out;
623	  };
624	  for (let f = 0; f < 6; f++) {
625	    const data = new Uint16Array(N * N * 4);
626	    for (let y = 0; y < N; y++) {
627	      for (let x = 0; x < N; x++) {
628	        const a = ((x + 0.5) / N) * 2 - 1, b = ((y + 0.5) / N) * 2 - 1;
629	        radiance(faceDir(f, a, b).normalize(), col);
630	        const i = (y * N + x) * 4;
631	        data[i] = THREE.DataUtils.toHalfFloat(col.r);
632	        data[i + 1] = THREE.DataUtils.toHalfFloat(col.g);
633	        data[i + 2] = THREE.DataUtils.toHalfFloat(col.b);
634	        data[i + 3] = THREE.DataUtils.toHalfFloat(1);
635	      }
636	    }
637	    const t = new THREE.DataTexture(data, N, N, THREE.RGBAFormat, THREE.HalfFloatType);
638	    t.colorSpace = THREE.LinearSRGBColorSpace;
639	    t.needsUpdate = true;
640	    faces.push(t);
641	  }
642	  const cube = new THREE.CubeTexture(faces as unknown as HTMLImageElement[]);
643	  cube.type = THREE.HalfFloatType;
644	  cube.format = THREE.RGBAFormat;
645	  cube.colorSpace = THREE.LinearSRGBColorSpace;
646	  cube.minFilter = THREE.LinearFilter;
647	  cube.magFilter = THREE.LinearFilter;
648	  cube.generateMipmaps = false;
649	  cube.needsUpdate = true;
650	  tubeEnvs[variant] = cube;
651	  return cube;
652	}
