686	    c = mix(c, vec3(1.0514, 0.9607, 0.8204), 1.0 - smoothstep(0.02, 0.05, v));         // pale top edge
687	    float sp = exp(-pow((u - 0.36) / 0.022, 2.0)) + exp(-pow((u - 0.64) / 0.022, 2.0));
688	    c += vec3(1.3, 1.2, 1.0) * sp * smoothstep(0.1, 0.16, v) * (1.0 - smoothstep(0.36, 0.44, v));
689	  }
690	  return c * mix(0.78, 1.0, ndv);
