700	/**
701	 * "Light at the end of the tunnel" (ref 05): a warm radial glow filling the tube cross-section at the end
702	 * of the straight 05 current. Opaque yellow-white core → gold → warm magenta → transparent rim, HDR so the
703	 * core blooms a little. It fades with the CAMERA distance to its own centre: full beyond `fade.y`, gone
704	 * inside `fade.x` (the rider approaching 06 sees the arch hall open up) and again beyond `fade.w` (far
705	 * stages never see it). Unit circle in local XY, facing +Z.
706	 */
707	export function tunnelEndGlowMaterial(fade = new THREE.Vector4(14, 30, 95, 120)): THREE.ShaderMaterial {
708	  return new THREE.ShaderMaterial({
709	    uniforms: {
710	      uFade: { value: fade },
711	      uOpacity: { value: 1 },
712	      // wave 7: smaller pale core inside an ORANGE halo (ref 05 VP: hot core ≈115 px², glow radius 13/20 px,
713	      // r 16–24 (248,169,89), r 24–32 (244,134,76); live was a 289 px² pale-yellow disc, r 16–24 (255,220,139))
714	      uCore: { value: new THREE.Color(3.0, 2.75, 2.1) },
715	      uGold: { value: new THREE.Color(1.6, 0.85, 0.32) },
716	      uWarm: { value: new THREE.Color(1.05, 0.42, 0.2) },
717	      uRim: { value: new THREE.Color(0.8, 0.3, 0.2) },
718	    },
719	    vertexShader: /* glsl */ `varying vec2 vUv; varying float vFade; uniform vec4 uFade;
720	      void main(){
721	        vUv = uv;
722	        float d = distance(cameraPosition, (modelMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz);
723	        vFade = smoothstep(uFade.x, uFade.y, d) * (1.0 - smoothstep(uFade.z, uFade.w, d));
724	        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
725	      }`,
726	    fragmentShader: /* glsl */ `varying vec2 vUv; varying float vFade; uniform vec3 uCore; uniform vec3 uGold; uniform vec3 uWarm; uniform vec3 uRim; uniform float uOpacity;
727	      void main(){
728	        float r = length(vUv - 0.5) * 2.0;
729	        vec3 c = mix(uRim, uWarm, smoothstep(1.0, 0.6, r));
730	        c = mix(c, uGold, smoothstep(0.62, 0.25, r));
731	        c = mix(c, uCore, smoothstep(0.34, 0.02, r));
732	        float a = (1.0 - smoothstep(0.82, 1.0, r)) * vFade * uOpacity;
733	        if (a < 0.003) discard;
734	        gl_FragColor = vec4(c, a);
735	        #include <tonemapping_fragment>
736	        #include <colorspace_fragment>
737	      }`,
738	    transparent: true,
739	    depthWrite: false,
740	    fog: false,
741	  });
742	}
