744	/**
745	 * Far stream of the 05 forced-perspective tunnel (ForcedTunnel.chordGeometry): the water surface beyond
746	 * the real ribbon, seen only as a thin winding band toward the vanishing point — a cyan core meandering
747	 * between two hot-pink bands, blue edges, white foam lips, glossy flow streaks, warming into the VP glow
748	 * with the virtual depth (`fgExtra`). Unlit (it is tiny on screen); morph "open" handled by three.
749	 */
750	export function farRiverMaterial(glow: FarGlow): THREE.MeshBasicMaterial {
751	  const mat = new THREE.MeshBasicMaterial({ color: '#ffffff', fog: false });
752	  const uniforms = {
753	    uRivCore: { value: new THREE.Color('#0aa2f6') },
754	    uRivBand: { value: new THREE.Color('#ee2fd8') },
755	    uRivEdge: { value: new THREE.Color('#1677e8') },
756	    uRivFoam: { value: new THREE.Color('#f4eeff') },
757	    uRivGlow: { value: new THREE.Color(glow.color) },
758	    uRivGlowR: { value: new THREE.Vector3(glow.near, glow.far, glow.strength) },
759	  };
760	  mat.onBeforeCompile = (shader) => {
761	    Object.assign(shader.uniforms, uniforms);
762	    shader.vertexShader = shader.vertexShader
763	      .replace('#include <common>', '#include <common>\nattribute float fgExtra; varying float vRivDist; varying vec2 vRivUv;')
764	      .replace('#include <uv_vertex>', '#include <uv_vertex>\nvRivUv = uv;')
765	      .replace('#include <project_vertex>', '#include <project_vertex>\nvRivDist = length(mvPosition.xyz) + fgExtra;');
766	    shader.fragmentShader = shader.fragmentShader
767	      .replace('#include <common>', `#include <common>
768	varying float vRivDist; varying vec2 vRivUv;
769	uniform vec3 uRivCore; uniform vec3 uRivBand; uniform vec3 uRivEdge; uniform vec3 uRivFoam; uniform vec3 uRivGlow; uniform vec3 uRivGlowR;`)
770	      .replace('#include <color_fragment>', `#include <color_fragment>
771	{
772	  float x = vRivUv.x * 2.0 - 1.0;
773	  float u = vRivUv.y;
774	  float cx = 0.3 * sin(u * 0.09 + 0.6) * (1.0 - 0.5 * smoothstep(20.0, 80.0, u));            // the cyan core meanders (ref: S-bends to the VP)
775	  float t = abs(x - cx);
776	  vec3 col = uRivCore;
777	  col = mix(col, uRivBand, smoothstep(0.14, 0.22, t) * (1.0 - smoothstep(0.44, 0.52, t)));
778	  col = mix(col, uRivEdge, smoothstep(0.5, 0.6, t) * 0.6);
779	  float st = pow(0.5 + 0.5 * sin((x - cx) * 46.0), 12.0);   // flow lines along the stream
780	  col += vec3(0.6, 0.8, 1.0) * st * 0.15;
781	  // cloud-like foam banks on both sides (purple wall above them stays visible)
782	  float bump = 0.06 * sin(u * 1.3 + x * 7.0) * sin(u * 0.7 - x * 11.0);
783	  float foam = smoothstep(0.74 + bump, 0.84 + bump, abs(x));
784	  col = mix(col, uRivFoam * (0.86 + 0.14 * sin(u * 2.1 + x * 19.0)), foam);
785	  float fg = smoothstep(uRivGlowR.x, uRivGlowR.y, vRivDist);
786	  col = mix(col, uRivGlow, min(0.9, fg * fg * uRivGlowR.z));
787	  diffuseColor.rgb = col * 0.88;
788	}`);
789	  };
790	  mat.customProgramCacheKey = () => 'far-river-v4';
791	  return mat;
792	}
