698	function buildPourStream(from: THREE.Vector3, floorY: number, dirX: number) {
699	  const pts: THREE.Vector3[] = [];
700	  const h = from.y - floorY;
701	  for (let i = 0; i <= 16; i++) {
702	    const t = i / 16;
703	    pts.push(new THREE.Vector3(from.x + dirX * 2.2 * t, from.y - h * t * t, from.z));
704	  }
705	  const curve = new THREE.CatmullRomCurve3(pts);
706	  const tex = canvasTexture(64, 256, (c, w, h2) => {
707	    const gr = c.createLinearGradient(0, 0, w, 0);
708	    gr.addColorStop(0, 'rgba(160,240,255,0.15)');
709	    gr.addColorStop(0.5, 'rgba(255,255,255,0.95)');
710	    gr.addColorStop(1, 'rgba(160,240,255,0.15)');
711	    c.fillStyle = gr;
712	    c.fillRect(0, 0, w, h2);
713	    for (let i = 0; i < 40; i++) {
714	      c.fillStyle = 'rgba(255,255,255,0.8)';
715	      c.fillRect(Math.random() * w, Math.random() * h2, 2, 10 + Math.random() * 20);
716	    }
717	  });
718	  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
719	  const mat = new THREE.MeshBasicMaterial({ map: tex, color: '#bff6ff', transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide, toneMapped: false });
720	  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 0.32, 8), mat);
721	  return { mesh, update: (t: number) => { tex.offset.y = -t * 2.2; } };
722	}
