253	/**
254	 * Ref 05 ring (wave 4): a ROUNDED gold band with a double contour — a thick half-round main band (the
255	 * camera-facing body catches a bright highlight on its crown and falls to copper in its shadowed lower
256	 * half) and, on the camera side (−z), a thin half-round lip separated by a narrow dark groove. Radial
257	 * values are fractions of the ring radius (1 = wall), axial values world units. Lathe around local Z,
258	 * traversed +z → −z so the faces point inward.
259	 */
260	export function roundBandGeometry(height = 0.095, width = 0.78, lipHeight = 0.045, lipWidth = 0.26, groove = 0.07, segments = 96): THREE.BufferGeometry {
261	  const w = (width + groove + lipWidth) / 2;
262	  const yc = w - width / 2, a = width / 2;
263	  const yl = -w + lipWidth / 2, al = lipWidth / 2;
264	  const pts: THREE.Vector2[] = [];
265	  const dup = (x: number, y: number) => { pts.push(new THREE.Vector2(x, y), new THREE.Vector2(x, y)); };
266	  pts.push(new THREE.Vector2(1.03, w));
267	  dup(1.0, w);
268	  for (let i = 1; i < 12; i++) {
269	    const f = (i / 12) * Math.PI;
270	    pts.push(new THREE.Vector2(1 - height * Math.sin(f), yc + a * Math.cos(f)));
271	  }
272	  dup(1.0, yc - a);
273	  pts.push(new THREE.Vector2(1.0 - height * 0.04, yc - a - groove * 0.5));
274	  dup(1.0, yl + al);
275	  for (let i = 1; i < 7; i++) {
276	    const f = (i / 7) * Math.PI;
277	    pts.push(new THREE.Vector2(1 - lipHeight * Math.sin(f), yl + al * Math.cos(f)));
278	  }
279	  dup(1.0, -w);
280	  pts.push(new THREE.Vector2(1.03, -w));
281	  const g = new THREE.LatheGeometry(pts, segments);
282	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
283	  return g;
284	}
