308	/** Same rings at an explicit list of path positions (e.g. one evenly spaced set per tunnel section). */
309	export function buildRingsAt(path: TubePath, list: number[], material: THREE.Material, opts: RingOpts = {}, spacing = 9): THREE.InstancedMesh {
310	  const tube = opts.tube ?? 0.075;
311	  const collar = opts.band ?? opts.collar;
312	  const geo = opts.band ? bandGeometry(opts.band) : opts.collar ? collarGeometry(opts.collar.depth, opts.collar.lip, opts.collar.width, opts.collar.segments) : new THREE.TorusGeometry(1, tube, 14, 72);
313	  const n = Math.max(1, list.length) * (opts.double ? 2 : 1);
314	  const mesh = new THREE.InstancedMesh(geo, material, n);
315	  const m = new THREE.Matrix4();
316	  const q = new THREE.Quaternion();
317	  const basis = new THREE.Matrix4();
318	  const c = new THREE.Vector3();
319	  let k = 0;
320	  for (const s of list) {
321	    for (let dbl = 0; dbl < (opts.double ? 2 : 1); dbl++) {
322	      const ss = s + dbl * spacing * 0.16;
323	      const f = path.frame(ss);
324	      const r = path.radius(ss) - (opts.inset ?? 0.05) + (opts.extra ?? 0);
325	      c.copy(f.pos).addScaledVector(f.up, path.radius(ss) - path.depth(ss));
326	      // (right, up, tan) is left-handed (right = tan × up), so the quaternion below is not the intended
327	      // frame: band rings (05 only) use the right-handed (−right, up, tan) so their lip really sits on the
328	      // camera side (−z); collar/torus rings (04/06/07) keep the legacy orientation unchanged
329	      if (opts.band) basis.makeBasis(f.right.clone().negate(), f.up, f.tan);
330	      else basis.makeBasis(f.right, f.up, f.tan);
331	      q.setFromRotationMatrix(basis);
332	      const sc = dbl ? r * 0.985 : r;
333	      // a collar keeps its axial width in world units; a torus scales uniformly
334	      m.compose(c, q, new THREE.Vector3(sc, sc, collar ? 1 : sc * (dbl ? 0.6 : 1)));
335	      mesh.setMatrixAt(k++, m);
336	    }
337	  }
338	  mesh.count = k;
339	  mesh.instanceMatrix.needsUpdate = true;
340	  mesh.frustumCulled = false;
341	  return mesh;
342	}
