361	    skip?: (s: number, centre: THREE.Vector3, size: number) => boolean;
362	    /** explicit lid positions along the path (default: s0, s0 + spacing, … s1) */
363	    positions?: number[];
364	    /**
365	     * 'hood' (legacy 06/07 D-hood), 'dome' (half puck with a domed cap) or 'slab' (ref 05 wave 4: a flat
366	     * copper-gold half-disc lid standing out of the wall — flat underside, rounded edges, a straight
367	     * polished rim band and a flat top, like the ref's wall-mounted nozzle lids)
368	     */
369	    shape?: 'hood' | 'dome' | 'slab';
