371	): THREE.InstancedMesh {
372	  const geo = wallLidGeometry(opts.shape ?? 'hood', opts.thickness ?? 0.42);
373	  const list: number[] = opts.positions ?? [];
374	  if (!opts.positions) for (let s = s0; s <= s1 + 1e-6; s += spacing) list.push(s);
375	  const n = Math.max(1, list.length) * 2;
376	  const mesh = new THREE.InstancedMesh(geo, material, n);
377	  const size = opts.size ?? 1.6;
378	  const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 18);
379	  const tilt = ang + THREE.MathUtils.degToRad(opts.droopDeg ?? 20);
380	  const c = new THREE.Vector3(), dir = new THREE.Vector3(), X = new THREE.Vector3(), Y = new THREE.Vector3(), Z = new THREE.Vector3();
