382	  let k = 0;
383	  for (const s of list) {
384	    for (const side of [1, -1]) {
385	      const f = path.frame(s);
386	      const r = path.radius(s);
387	      tubeCenterAt(path, s, c);
388	      dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
389	      const sz = size * Math.min(1.4, r / 7.6);
390	      // in the cross-section: +X points inward (radially, then drooped toward the stream), +Y is the
391	      // hood's top normal, +Z runs along the tube (the D's straight edge)
392	      X.copy(f.right).multiplyScalar(-Math.cos(tilt) * side).addScaledVector(f.up, -Math.sin(tilt)).normalize();
393	      Y.copy(f.right).multiplyScalar(-Math.sin(tilt) * side).addScaledVector(f.up, Math.cos(tilt)).normalize();
394	      Z.crossVectors(X, Y).normalize();
395	      basis.makeBasis(X, Y, Z);
396	      q.setFromRotationMatrix(basis);
397	      p.copy(c).addScaledVector(dir, r - sz * (opts.sink ?? 0.12));
398	      if (opts.skip?.(s, p.clone().addScaledVector(X, sz * 0.5), sz)) continue;
399	      m.compose(p, q, new THREE.Vector3(sz, sz, sz * (opts.stretch ?? 1.25)));
400	      mesh.setMatrixAt(k++, m);
401	    }
402	  }
403	  mesh.count = k;
404	  mesh.instanceMatrix.needsUpdate = true;
405	  mesh.frustumCulled = false;
406	  return mesh;
407	}
