416	    ]
417	    : shape === 'slab'
418	      ? [
419	        // flat underside with a shallow recess and an inner ring, rounded lower edge, straight rim band,
420	        // rounded upper edge, flat (very slightly crowned) top
421	        // (edge rounding scales with the thickness so thin pucks stay valid)
