428	      ];
429	  // half revolution (phi 0..π → local +X): the open cut face lies in the wall plane x = 0
430	  const geo = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), segments ?? (shape === 'hood' ? 28 : 24), 0, Math.PI);
